168	                                       key: "value" 
169	                                    }
170	                                }
171	                            }
172	                            $anotherLocal: $local.nested.deepNesting.key
173	                            val: $anotherLocal
174	                        }
175		        		}
176		        	}
177		        `,
178				expectContains: "$local",
179			},
180			{
181				name: "status details with import statement should work",
182				input: `
183					attributes: {
184						status: {
185							details: #"""
186								import "strconv"
